// components/noticeboard/panels/NoticeBoardList.tsx
// ═══════════════════════════════════════════════════════════════════
// 홈 공지사항 노트 (UPDATE 노트 · 필터 · 리스트 · 팝업 상세)
// ═══════════════════════════════════════════════════════════════════
//
// 이 컴포넌트 하나가 "노트" 그 자체:
//   · 배경: /svg/update-note.svg (연회색 종이) + 드롭섀도우
//   · 상단: UPDATE 글씨(Monofett) + 마스킹테이프 SVG
//   · 상단 우측: 카테고리 필터
//   · 본문: 공지 항목 리스트 (색점 · 라벨 · 제목 · 날짜)
//   · 클릭 시 팝업으로 상세 표시 (Portal, AuthModal 톤)
//
// 부모(BoardCover) 는 위치만 잡고 <NoticeBoardList /> 만 렌더한다.
//
// ── 2026-08 리뉴얼 (Anima 시안) ──
//   기존 flat prop 및 외부 필터바(NoticeBoardFilter) 제거.
//   컴포넌트 하나로 모양·상태·요소 전부 캡슐화.
//   리스트 컨테이너 고정 높이 → 항목 수에 따라 노트 크기 안 흔들림.
//   팝업은 Portal 로 document.body 에 렌더 (스테이지 transform 밖).
//
// 접근 정책:
//   RLS 는 익명 포함 전체 SELECT 허용.
//
// 갱신:
//   마운트 시 로드. GM 편집 반영은 새로고침 필요. Realtime 은 후속.
// ═══════════════════════════════════════════════════════════════════

"use client";

import { useEffect, useMemo, useState, type CSSProperties } from "react";
import { createPortal } from "react-dom";
import {
  NOTICE_CATEGORIES,
  NOTICE_CATEGORY_COLOR,
  NOTICE_CATEGORY_LABEL,
  listNotices,
  type Notice,
  type NoticeCategory,
} from "@/lib/notices-helpers";

// ────────────────────────────────────────────────────────────────────
// 폰트·상수
// ────────────────────────────────────────────────────────────────────
const JUA  = "'Jua', sans-serif";
const BODY = "'Gowun Dodum', sans-serif";

const LIST_HEIGHT = 110;  
const PAGE_SIZE   = 3;  

type Filter = "all" | NoticeCategory;

// ═══════════════════════════════════════════════════════════════════
// 본체
// ═══════════════════════════════════════════════════════════════════

export default function NoticeBoardList() {
  const [notices, setNotices] = useState<Notice[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState<Filter>("all");
  const [selected, setSelected] = useState<Notice | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    listNotices()
      .then((rows) => {
        if (!cancelled) setNotices(rows);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  const filtered = useMemo(() => {
    if (filter === "all") return notices;
    return notices.filter((n) => n.category === filter);
  }, [notices, filter]);

  // ── 페이지네이션 ──
  const [page, setPage] = useState(0);

  useEffect(() => { setPage(0); }, [filter]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage  = Math.min(page, pageCount - 1);   // 범위 밖이면 자동 보정
  const pageItems = filtered.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);

  return (
    <div style={noteStyle}>

      <img
        src="/svg/update-note.svg"
        alt=""
        style={noteBgStyle}
      />

      {/* 마스킹테이프 (노트 안 상단) */}
      <div style={tapeLeftStyle}  dangerouslySetInnerHTML={{ __html: cropTape("0 9 121 110") }} />
      <div style={tapeRightStyle} dangerouslySetInnerHTML={{ __html: cropTape("467 0 121 109") }} />

      {/* UPDATE 글씨 */}
      <div style={updateTitleStyle}>UPDATE</div>

      {/* 필터 (UPDATE 옆 우상단, 같은 선상) */}
      <div style={filterSlotStyle}>
        <FilterBar filter={filter} onChange={setFilter} />
      </div>

      {/* 리스트 */}
      <div style={listContainerStyle}>
        {loading ? (
          <EmptyLine text="불러오는 중입니다." />
        ) : filtered.length === 0 ? (
          <EmptyLine
            text={
              filter === "all"
                ? "등록된 공지가 없습니다."
                : "이 분류에 해당하는 공지가 없습니다."
            }
          />
        ) : (
          <ul style={ulStyle}>
            {pageItems.map((n) => (
              <NoticeRow
                key={n.id}
                notice={n}
                onClick={() => setSelected(n)}
              />
            ))}
          </ul>
        )}
      </div>

      {/* 페이지 점 (공지가 페이지당 개수를 넘으면 표시) */}
      {!loading && pageCount > 1 ? (
        <div style={dotsStyle}>
          {Array.from({ length: pageCount }).map((_, i) => (
            <button
              key={i}
              type="button"
              onClick={() => setPage(i)}
              aria-label={`${i + 1}페이지`}
              style={{
                ...dotStyle,
                background: i === safePage ? "#3f88f9" : "#c5d8ef",
              }}
            />
          ))}
        </div>
      ) : null}

      {/* 상세 팝업 */}
      {selected ? (
        <NoticePopup notice={selected} onClose={() => setSelected(null)} />
      ) : null}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// 서브 : 필터 바
// ═══════════════════════════════════════════════════════════════════

function FilterBar({
  filter,
  onChange,
}: {
  filter: Filter;
  onChange: (f: Filter) => void;
}) {
  const items: { key: Filter; label: string }[] = [
    { key: "all", label: "전체" },
    ...NOTICE_CATEGORIES.map((c) => ({
      key: c as Filter,
      label: NOTICE_CATEGORY_LABEL[c],
    })),
  ];

  return (
    <div style={filterBarStyle}>
      {items.map((it) => {
        const active = filter === it.key;
        return (
          <button
            key={it.key}
            type="button"
            onClick={() => onChange(it.key)}
            style={{
              ...filterBtnStyle,
              background: active ? "#3f88f9" : "transparent",
              color:      active ? "#fff"    : "#5b7ea6",
              borderColor: active ? "#3f88f9" : "#bfd6f0",
            }}
          >
            {it.label}
          </button>
        );
      })}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// 서브 : 공지 항목
// ═══════════════════════════════════════════════════════════════════

function NoticeRow({
  notice,
  onClick,
}: {
  notice: Notice;
  onClick: () => void;
}) {
  const color = NOTICE_CATEGORY_COLOR[notice.category];
  const date  = formatDate(notice.createdAt);

  return (
    <li style={rowStyle}>
      <button type="button" onClick={onClick} style={rowBtnStyle}>
        <span
          style={{
            width: 8,
            height: 8,
            borderRadius: "50%",
            background: color.fg,
            flexShrink: 0,
          }}
        />
        <span
          style={{
            fontFamily: JUA,
            fontSize: 11,
            color: color.fg,
            width: 34,
            flexShrink: 0,
          }}
        >
          {NOTICE_CATEGORY_LABEL[notice.category]}
        </span>
        <span
          style={{
            fontFamily: BODY,
            fontSize: 13,
            color: "#1a335e",
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
            minWidth: 0,
            flex: 1,
            textAlign: "left",
          }}
        >
          {notice.title}
        </span>
        <span
          style={{
            fontFamily: BODY,
            fontSize: 11,
            color: "#7fa8c9",
            flexShrink: 0,
          }}
        >
          {date}
        </span>
      </button>
    </li>
  );
}

// ═══════════════════════════════════════════════════════════════════
// 서브 : 상세 팝업 (Portal · AuthModal 톤)
// ═══════════════════════════════════════════════════════════════════

function NoticePopup({
  notice,
  onClose,
}: {
  notice: Notice;
  onClose: () => void;
}) {
  const color = NOTICE_CATEGORY_COLOR[notice.category];
  const date  = formatDate(notice.createdAt);
  const edited = notice.updatedAt !== notice.createdAt;

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  if (typeof document === "undefined") return null;

  const content = (
    <div style={popupBackdropStyle} onClick={onClose}>
      <div style={popupCardStyle} onClick={(e) => e.stopPropagation()}>
        <button type="button" onClick={onClose} style={popupCloseBtnStyle}>
          ✕
        </button>

        <span
          style={{
            display: "inline-block",
            fontFamily: JUA,
            fontSize: 12,
            background: color.bg,
            color: color.fg,
            padding: "3px 12px",
            borderRadius: 999,
          }}
        >
          {NOTICE_CATEGORY_LABEL[notice.category]}
        </span>

        <h2 style={popupTitleStyle}>{notice.title}</h2>

        <div style={popupDateStyle}>
          {date}
          {edited ? ` · 수정됨 (${formatDate(notice.updatedAt)})` : null}
        </div>

        <div style={popupBodyStyle}>{notice.body}</div>
      </div>
    </div>
  );

  return createPortal(content, document.body);
}

// ═══════════════════════════════════════════════════════════════════
// 서브 : 빈 상태 라인
// ═══════════════════════════════════════════════════════════════════

function EmptyLine({ text }: { text: string }) {
  return (
    <div
      style={{
        fontFamily: BODY,
        fontSize: 13,
        color: "#7fa8c9",
        textAlign: "center",
        padding: "40px 0",
      }}
    >
      {text}
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────
// 헬퍼
// ────────────────────────────────────────────────────────────────────

function formatDate(iso: string | null | undefined): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const m  = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${m}/${dd}`;
}

function cropTape(viewBox: string): string {
  return UPDATE_TAPE_SVG.replace('viewBox="0 0 588 119"', `viewBox="${viewBox}"`);
}

// ────────────────────────────────────────────────────────────────────
